package com.odysseus.streaming.model;

import com.fasterxml.jackson.annotation.JsonProperty;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Objects;

/**
 * Model representing an incident alert generated by Flink Complex Event Processing (CEP).
 * Dispatched to Amazon SQS FIFO queue with deterministic SHA-256 deduplication.
 */
public class AlertEvent implements Serializable {

    private static final long serialVersionUID = 1L;

    @JsonProperty("alert_id")
    private String alertId;

    @JsonProperty("sensor_id")
    private String sensorId;

    @JsonProperty("pattern_name")
    private String patternName;

    @JsonProperty("detected_timestamp")
    private long detectedTimestamp;

    @JsonProperty("trigger_temperature")
    private double triggerTemperature;

    @JsonProperty("trigger_vibration")
    private double triggerVibration;

    @JsonProperty("severity")
    private String severity;

    @JsonProperty("details")
    private String details;

    public AlertEvent() {
    }

    public AlertEvent(String alertId, String sensorId, String patternName,
                      long detectedTimestamp, double triggerTemperature,
                      double triggerVibration, String severity, String details) {
        this.alertId = alertId;
        this.sensorId = sensorId;
        this.patternName = patternName;
        this.detectedTimestamp = detectedTimestamp;
        this.triggerTemperature = triggerTemperature;
        this.triggerVibration = triggerVibration;
        this.severity = severity;
        this.details = details;
    }

    /**
     * Computes a deterministic SHA-256 token used as SQS DeduplicationId and DynamoDB TTL Key.
     * Prevents alert storms during Flink checkpoint replays or replay-driven failovers.
     */
    public static String calculateIdempotencyToken(String sensorId, String patternName, long windowStart, long windowEnd) {
        String raw = sensorId + ":" + patternName + ":" + windowStart + ":" + windowEnd;
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }

    public String getAlertId() {
        return alertId;
    }

    public void setAlertId(String alertId) {
        this.alertId = alertId;
    }

    public String getSensorId() {
        return sensorId;
    }

    public void setSensorId(String sensorId) {
        this.sensorId = sensorId;
    }

    public String getPatternName() {
        return patternName;
    }

    public void setPatternName(String patternName) {
        this.patternName = patternName;
    }

    public long getDetectedTimestamp() {
        return detectedTimestamp;
    }

    public void setDetectedTimestamp(long detectedTimestamp) {
        this.detectedTimestamp = detectedTimestamp;
    }

    public double getTriggerTemperature() {
        return triggerTemperature;
    }

    public void setTriggerTemperature(double triggerTemperature) {
        this.triggerTemperature = triggerTemperature;
    }

    public double getTriggerVibration() {
        return triggerVibration;
    }

    public void setTriggerVibration(double triggerVibration) {
        this.triggerVibration = triggerVibration;
    }

    public String getSeverity() {
        return severity;
    }

    public void setSeverity(String severity) {
        this.severity = severity;
    }

    public String getDetails() {
        return details;
    }

    public void setDetails(String details) {
        this.details = details;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        AlertEvent that = (AlertEvent) o;
        return Objects.equals(alertId, that.alertId) && Objects.equals(sensorId, that.sensorId);
    }

    @Override
    public int hashCode() {
        return Objects.hash(alertId, sensorId);
    }

    @Override
    public String toString() {
        return "AlertEvent{" +
                "alertId='" + alertId + '\'' +
                ", sensorId='" + sensorId + '\'' +
                ", severity='" + severity + '\'' +
                ", triggerTemp=" + triggerTemperature +
                ", triggerVib=" + triggerVibration +
                '}';
    }
}

